import React, { useEffect } from 'react';
import { List, Card } from 'antd';
import { createSlice, configureStore } from '@reduxjs/toolkit';
import axios from 'axios';

const pokemonSlice = createSlice({
  name: 'pokemon',
  initialState: { pokemons: [] },
  reducers: {
    setPokemons: (state, action) => {
      state.pokemons = action.payload;
    },
  },
});

const { setPokemons } = pokemonSlice.actions;
const store = configureStore({ reducer: pokemonSlice.reducer });

const fetchPokemons = () => async (dispatch) => {
  const response = await axios.get('https://pokeapi.co/api/v2/pokemon?limit=151');
  const pokemons = await Promise.all(
    response.data.results.map(async (pokemon) => {
      const pokemonResponse = await axios.get(pokemon.url);
      return {
        name: pokemon.name,
        image: pokemonResponse.data.sprites.front_default,
      };
    })
  );
  dispatch(setPokemons(pokemons));
};

store.dispatch(fetchPokemons());

const PokemonList = () => {
  const { pokemons } = store.getState();

  return (
    <List
      grid={{ gutter: 16, column: 3 }}
      dataSource={pokemons}
      renderItem={(item) => (
        <List.Item>
          <Card title={item.name} cover={<img alt={item.name} src={item.image} />}>
            <Card.Meta description={item.name} />
          </Card>
        </List.Item>
      )}
    />
  );
};

const App = () => (
  <div style={{ padding: '24px' }}>
    <h1 style={{ textAlign: 'center' }}>Pokémon List</h1>
    <PokemonList />
  </div>
);

export default App;
